UPDATE `tbpo_barang` b
JOIN `_tmp_tbpo_barang_rollback_isi_kemasan_20260820` t ON t.`kode_barang` = b.`kode_barang`
SET b.`isi` = t.`isi`,
    b.`kemasan` = t.`kemasan`
WHERE NOT (b.`isi` <=> t.`isi` AND b.`kemasan` <=> t.`kemasan`);
